// Replaces the network Switch. One template serves every network: the AGN, Multinet and AusNet
// templates are identical apart from two header cells, and the offer rate already comes from Base 2.
// To use a separate copy for a network, paste its file ID below. Make it with File > Make a copy of
// the default template so the tab gids below still match.
const body = $('Generate E SME to C&I Comparaison1').first().json.body || {};
const row = $('Get row(s) in sheet7').first().json;

const DEFAULT_TEMPLATE_ID = '1vxMA8cFU_z8Dot5cSISknP5-Xm8EkuZguJsK89WZd9E';
const TEMPLATE_BY_NETWORK = {
  'Australian Gas Networks': DEFAULT_TEMPLATE_ID,
  'Multinet': DEFAULT_TEMPLATE_ID,
  'AusNet': DEFAULT_TEMPLATE_ID,
};

const network = String(body.sme_gas_network || '').trim();
const templateId = TEMPLATE_BY_NETWORK[network];
if (!templateId) {
  throw new Error(`No SME gas template for network "${network}". Choose Multinet, Australian Gas Networks or AusNet in Base 2.`);
}
if (!(Number(body.offer1GasRate) > 0)) {
  throw new Error('No Alinta offer rate was sent from Base 2, so the comparison would be wrong. Check the network and bill usage.');
}

return [{
  json: {
    ...row,
    network,
    template_id: templateId,
    gid_summary: 457052602,
    gid_offers_report: 730527680,
    gid_engagement_form: 1871010394,
  },
}];

// SME GAS PDF PACK: 1. Comparison Summary, 2. Offer Report, 3. Engagement Form
const summaryBinary = $node["HTTP Request47"].binary?.data;
const offerReportBinary = $node["HTTP Request33"].binary?.data;
const engagementFormBinary = $node["HTTP Request53"].binary?.data;

const businessName = $('Get row(s) in sheet7').first().json['Business Name'] || 'UnknownBusiness';
const mrin = $('Get row(s) in sheet21').first().json['NMI / MRIN'] || 'UnknownMRIN';
const userEmail = $('Generate E SME to C&I Comparaison1').first().json?.body?.user_email || 'UnknownUser';

if (!summaryBinary || !offerReportBinary || !engagementFormBinary) {
  return [{ json: {
    message: 'Missing one or more SME gas PDFs',
    user_email: userEmail,
    gasComparisonSummary: summaryBinary ? 'Present' : 'Missing',
    gasOfferReport: offerReportBinary ? 'Present' : 'Missing',
    engagementForm: engagementFormBinary ? 'Present' : 'Missing',
  } }];
}

summaryBinary.fileName = `Gas Comparison Summary for ${businessName} MRIN ${mrin}.pdf`;
offerReportBinary.fileName = `Gas Offer Report for ${businessName} MRIN ${mrin}.pdf`;
engagementFormBinary.fileName = `Gas Engagement Form for ${businessName} MRIN ${mrin}.pdf`;

// Binary keys kept as-is: Merge PDFs6 reads these names.
return [{
  json: { message: 'SME gas PDFs ready', user_email: userEmail, business_name: businessName, mrin },
  binary: {
    GasComparisonSummaryFile: summaryBinary,
    gasofferreportFile: offerReportBinary,
    engagementformFile: engagementFormBinary,
  },
}];

// Run Once for All Items
// Client-ready HTML email for SME to SME gas reviews (Alinta BusinessDeal Flex).
// Figures come from the "Gas Comparison Summary" tab, so the email matches the attached PDF.

const rows = items
  .map(item => item.json)
  .filter(Boolean)
  .sort((a, b) => Number(a.row_number ?? 0) - Number(b.row_number ?? 0));

const sourceBody = $('Generate E SME to C&I Comparaison1').first()?.json?.body ?? {};
const invoice = sourceBody.full_invoice_data?.gas_sme_invoicedetails ?? {};

function clean(value) { return String(value ?? '').replace(/\s+/g, ' ').trim(); }
function esc(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}
function firstNonBlank(...values) {
  for (const value of values) { const c = clean(value); if (c) return c; }
  return '';
}
function getFirstName(value) {
  const c = clean(value);
  if (!c || c.includes('@')) return 'there';
  return c.split(/\s+/)[0];
}
function parseNumber(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const c = String(value).replace(/[$,%]/g, '').trim();
  if (!c || c.startsWith('#')) return null;
  const n = Number(c);
  return Number.isFinite(n) ? n : null;
}
function formatCurrency(value) {
  const n = parseNumber(value);
  if (n === null) return 'N/A';
  return n.toLocaleString('en-AU', { style: 'currency', currency: 'AUD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function extractMoneyValues(value) {
  return [...String(value ?? '').matchAll(/\$?\s*(-?[\d,]+(?:\.\d{1,4})?)/g)]
    .map(m => Number(m[1].replace(/,/g, ''))).filter(Number.isFinite);
}

// Sheet lookups: column 1 is the label, col_2 the value.
const reservedKeys = new Set(['row_number', 'col_2']);
const textKey = Object.keys(rows[0] ?? {}).find(k => !reservedKeys.has(k)) ?? 'Text';
const getText = row => clean(row?.[textKey]);
const getVal = row => clean(row?.col_2);
const findRow = label => rows.find(r => getText(r).toLowerCase() === clean(label).toLowerCase());
const findVal = label => { const r = findRow(label); return r ? getVal(r) : ''; };
const findTextIncludes = needle => {
  const r = rows.find(row => getText(row).toLowerCase().includes(clean(needle).toLowerCase()));
  return r ? getText(r) : '';
};
function rowAfterHeading(heading) {
  const i = rows.findIndex(r => getText(r).toLowerCase() === clean(heading).toLowerCase());
  if (i === -1) return '';
  const next = rows.slice(i + 1).find(r => getText(r) || getVal(r));
  return next ? (getText(next) || getVal(next)) : '';
}

// Details
const businessName = firstNonBlank(sourceBody.business_name, invoice.client_name, 'the client');
const firstName = getFirstName(firstNonBlank(sourceBody.contact_name, sourceBody.contact_email, sourceBody.client_email));
const siteAddress = firstNonBlank(invoice.site_address, sourceBody.site_address) || 'N/A';
const mrin = firstNonBlank(invoice.mrin, sourceBody.mrin) || 'N/A';
const currentRetailer = firstNonBlank(invoice.retailer, sourceBody.retailer) || 'N/A';
const proposedRetailer = firstNonBlank(sourceBody.offer1Retailer) || 'Alinta Energy';
const network = firstNonBlank(sourceBody.sme_gas_network);

// Costs from the summary tab
const annualLine = findVal('Annual Energy Cost');
const monthlyLine = findVal('Monthly Energy Cost');
const differenceLine = findVal('Year 1 Cost Difference');
const [currentAnnualCost = null, proposedAnnualCost = null] = extractMoneyValues(annualLine);
const [currentMonthlyCost = null, proposedMonthlyCost = null] = extractMoneyValues(monthlyLine);
const currentRate = firstNonBlank(findVal('Current Energy Rate')) || 'N/A';
const proposedRate = firstNonBlank(findVal('New Energy Rate')) || 'N/A';
const outcomePctLine = firstNonBlank(
  findTextIncludes('reduction in estimated annual energy cost'),
  findTextIncludes('increase in estimated annual energy cost'),
  findTextIncludes('no material change in estimated annual energy cost'),
);

let savings = null;
if (Number.isFinite(currentAnnualCost) && Number.isFinite(proposedAnnualCost)) {
  savings = currentAnnualCost - proposedAnnualCost;
} else {
  const d = extractMoneyValues(differenceLine)[0];
  if (Number.isFinite(d)) savings = /increase|higher|additional/i.test(differenceLine) ? -Math.abs(d) : Math.abs(d);
}

const outcome = savings === null
  ? { label: 'Estimated Year 1 Outcome', value: differenceLine || 'Refer to attached comparison', status: 'Gas Comparison Completed',
      background: '#f8faf9', border: '#dce5e2', colour: '#0f3d3e', outcomeText: differenceLine || 'Refer to attached comparison', outcomeColour: '#48615b' }
  : savings > 0
    ? { label: 'Estimated Year 1 Saving', value: formatCurrency(savings), status: 'Estimated Saving Identified',
        background: '#edf7f4', border: '#a9d2c8', colour: '#0f6b5f', outcomeText: `${formatCurrency(savings)} saving`, outcomeColour: '#0f6b5f' }
    : savings < 0
      ? { label: 'Estimated Year 1 Increase', value: formatCurrency(Math.abs(savings)), status: 'Cost Increase Identified',
          background: '#fff4df', border: '#e8bd72', colour: '#8a5200', outcomeText: `${formatCurrency(Math.abs(savings))} increase`, outcomeColour: '#a33a2b' }
      : { label: 'Estimated Year 1 Outcome', value: formatCurrency(0), status: 'Comparable Cost Outcome',
          background: '#f8faf9', border: '#dce5e2', colour: '#48615b', outcomeText: 'No material change', outcomeColour: '#48615b' };
const outcomeSubtext = outcomePctLine || 'Estimated across the first year of the proposed gas agreement';

const recommendedNextStep = firstNonBlank(
  rowAfterHeading('Recommended Next Step'),
  'Please review the attached gas comparison and engagement form and let us know if you would like to proceed with the proposed offer.',
);

const importantNotes = [];
const notesIndex = rows.findIndex(r => getText(r).toLowerCase() === 'important notes');
if (notesIndex !== -1) {
  for (const row of rows.slice(notesIndex + 1)) {
    const t = getText(row);
    if (!t) continue;
    if (/^ESG \(Environmental, Social, and Governance\) Impact$/i.test(t) || /^GHG Impact:?$/i.test(t) || /^©/.test(t)) break;
    importantNotes.push(t);
    if (importantNotes.length === 3) break;
  }
}

const td = 'padding:10px; border:1px solid #dce5e2;';
const tdLabel = 'padding:10px; background:#f8faf9; border:1px solid #dce5e2;';
const detailRow = (label, value) => `<tr><td style="${tdLabel} width:40%;"><strong>${esc(label)}</strong></td><td style="${td}">${esc(value)}</td></tr>`;

const html = `
<html>
<body style="margin:0; padding:0; background:#f4f7f6; font-family:Arial, Helvetica, sans-serif; color:#1f2933;">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f7f6; padding:24px 0;"><tr><td align="center">
<table width="680" cellpadding="0" cellspacing="0" style="width:680px; max-width:100%; background:#ffffff; border-radius:12px; overflow:hidden; border:1px solid #dce5e2;">

<tr><td style="background:#0f3d3e; padding:24px 28px; color:#ffffff; text-align:center;">
<div style="font-size:13px; letter-spacing:0.5px; text-transform:uppercase; color:#b7d8cf;">Gas Agreement Review</div>
<div style="font-size:24px; font-weight:bold; margin-top:6px; line-height:1.25;">${esc(outcome.status)}</div>
<div style="font-size:14px; color:#d7ebe5; margin-top:8px;">${esc(businessName)}</div>
</td></tr>

<tr><td style="padding:28px;">
<p style="margin:0 0 16px; font-size:15px; line-height:1.5;">Hi ${esc(firstName)},</p>
<p style="margin:0 0 20px; font-size:15px; line-height:1.6;">I hope you are well. We have reviewed your current gas arrangement against the proposed ${esc(proposedRetailer)} offer. Below is a summary of the estimated gas costs, energy rates and overall Year 1 outcome.</p>

<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; margin-bottom:24px; font-size:14px;">
${detailRow('Business', businessName)}
${detailRow('Site Address', siteAddress)}
${detailRow('MRIN', mrin)}
${detailRow('Current Retailer', currentRetailer)}
${detailRow('Proposed Retailer', proposedRetailer)}
${network ? detailRow('Gas Network', network) : ''}
</table>

<table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 24px; background:${outcome.background}; border:1px solid ${outcome.border}; border-radius:10px;">
<tr><td style="padding:22px; text-align:center;">
<div style="font-size:13px; color:${outcome.colour}; text-transform:uppercase; letter-spacing:0.4px; font-weight:bold;">${esc(outcome.label)}</div>
<div style="font-size:32px; color:${outcome.colour}; font-weight:bold; margin-top:6px;">${esc(outcome.value)}</div>
<div style="font-size:13px; color:${outcome.colour}; margin-top:7px;">${esc(outcomeSubtext)}</div>
</td></tr></table>

<div style="font-size:17px; font-weight:bold; color:#0f3d3e; margin-bottom:10px;">Current vs Proposed Gas Cost</div>
<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; margin-bottom:8px; font-size:13px;">
<tr>
<th align="left" style="padding:10px; background:#f1f5f4; border:1px solid #dce5e2;">Cost Measure</th>
<th align="right" style="padding:10px; background:#f1f5f4; border:1px solid #dce5e2;">Current</th>
<th align="right" style="padding:10px; background:#f1f5f4; border:1px solid #dce5e2;">Proposed</th>
<th align="right" style="padding:10px; background:#f1f5f4; border:1px solid #dce5e2;">Outcome</th>
</tr>
<tr><td style="${td} font-weight:bold;">Average Monthly Gas Cost</td><td align="right" style="${td}">${esc(formatCurrency(currentMonthlyCost))}</td><td align="right" style="${td}">${esc(formatCurrency(proposedMonthlyCost))}</td><td align="right" style="${td} color:#48615b;">Estimated</td></tr>
<tr><td style="${td} font-weight:bold;">Estimated Annual Gas Cost</td><td align="right" style="${td}">${esc(formatCurrency(currentAnnualCost))}</td><td align="right" style="${td}">${esc(formatCurrency(proposedAnnualCost))}</td><td align="right" style="${td} color:${outcome.outcomeColour}; font-weight:bold;">${esc(outcome.outcomeText)}</td></tr>
</table>
<p style="margin:0 0 24px; font-size:12px; line-height:1.5; color:#667a75;">Annual costs include the gas energy charges and the daily supply charge, based on your current invoice usage.</p>

<div style="font-size:17px; font-weight:bold; color:#0f3d3e; margin-bottom:10px;">Gas Energy Rate Comparison</div>
<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; margin-bottom:8px; font-size:13px;">
<tr><td style="${td} font-weight:bold;">Current Energy Rate</td><td style="${td}">${esc(currentRate)}</td></tr>
<tr><td style="${td} font-weight:bold;">Proposed Energy Rate</td><td style="${td} font-weight:bold; color:#0f6b5f;">${esc(proposedRate)}</td></tr>
</table>
<p style="margin:0 0 24px; font-size:12px; line-height:1.5; color:#667a75;">Rates are shown in dollars per gigajoule ($/GJ), including GST. Your usage is priced through each retailer's usage steps, so these are the average rates for your site.</p>

${importantNotes.length ? `
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f8faf9; border:1px solid #dce5e2; border-radius:10px; margin-bottom:24px;"><tr><td style="padding:18px;">
<div style="font-size:15px; font-weight:bold; color:#0f3d3e; margin-bottom:8px;">Important Notes</div>
<div style="font-size:13px; line-height:1.65; color:#48615b;">${importantNotes.map(n => `&bull; ${esc(n)}`).join('<br>')}</div>
</td></tr></table>` : ''}

<table width="100%" cellpadding="0" cellspacing="0" style="background:#f8faf9; border:1px solid #dce5e2; border-radius:10px; margin-bottom:24px;"><tr><td style="padding:18px;">
<div style="font-size:15px; font-weight:bold; color:#0f3d3e; margin-bottom:8px;">Attached for Review</div>
<div style="font-size:14px; line-height:1.7;">&bull; SME Gas Comparison Pack<br>&bull; Copy of the current gas invoice</div>
</td></tr></table>

<table width="100%" cellpadding="0" cellspacing="0" style="background:#edf7f4; border:1px solid #a9d2c8; border-radius:10px; margin-bottom:24px;"><tr><td style="padding:18px;">
<div style="font-size:16px; font-weight:bold; color:#0f3d3e; margin-bottom:10px;">Next Steps</div>
<div style="font-size:14px; line-height:1.7; color:#304f48;">${esc(recommendedNextStep)}<br><br>Once confirmed, our team will coordinate the new gas agreement and provide any required documentation for review and signature.</div>
</td></tr></table>

<p style="margin:0 0 14px; font-size:14px;">Kind regards,</p>
<p style="margin:0; font-size:14px; line-height:1.5;"><b>The Team</b><br>Australian Circular Economy Solutions</p>
<p style="margin:18px 0 0; font-size:14px; line-height:1.6;"><b>Carbon Zero Australasia</b><br>Australian Circular Economy Solutions Division<br>Direct: 0468 050 399<br>
Email: <a href="mailto:business@acesolutions.com.au" style="color:#0f6b5f;">business@acesolutions.com.au</a><br>
470 St Kilda Road, Melbourne VIC 3004<br>
Website: <a href="https://acesolutions.com.au" style="color:#0f6b5f;">acesolutions.com.au</a></p>
</td></tr>
</table>
</td></tr></table>
</body>
</html>`.trim();

return [{
  json: {
    subject: `Gas Agreement Review for ${businessName}`,
    html,
    businessName, firstName, siteAddress, mrin, network,
    currentRetailer, proposedRetailer,
    current_cost: currentAnnualCost ?? 0,
    new_cost: proposedAnnualCost ?? 0,
    annual_savings: savings ?? 0,
    currentMonthlyCost: currentMonthlyCost ?? 0,
    proposedMonthlyCost: proposedMonthlyCost ?? 0,
    currentAnnualCost: currentAnnualCost ?? 0,
    proposedAnnualCost: proposedAnnualCost ?? 0,
    currentRates: currentRate,
    proposedRates: proposedRate,
    recommendationStatus: outcome.status,
    year1CostDifference: outcome.outcomeText,
    importantNotes,
  },
}];

// FINAL SME GAS EMAIL ATTACHMENTS: 1. merged comparison pack, 2. the invoice that was compared
const mergedBinary = $node["Merge PDFs6"].binary?.data;
const invoiceBinary = $node["Download file2"].binary?.data;
const businessName = $('Get row(s) in sheet7').first().json['Business Name'] || 'UnknownBusiness';
const mrin = $('Get row(s) in sheet21').first().json['NMI / MRIN'] || 'UnknownMRIN';
const userEmail = $('Generate E SME to C&I Comparaison1').first().json?.body?.user_email || 'UnknownUser';

if (!mergedBinary || !invoiceBinary) {
  return [{ json: {
    message: 'Missing binary data for merged gas pack or invoice',
    user_email: userEmail,
    mergedBinary: mergedBinary ? 'Present' : 'Missing',
    invoiceBinary: invoiceBinary ? 'Present' : 'Missing',
  } }];
}

const mergedFileName = `SME Gas Comparison - ${businessName} - MRIN ${mrin}.pdf`;
const invoiceFileName = `Gas Invoice - ${businessName} - MRIN ${mrin}.pdf`;
mergedBinary.fileName = mergedFileName;
invoiceBinary.fileName = invoiceFileName;

return [{
  json: {
    message: 'SME gas comparison pack and invoice ready',
    user_email: userEmail,
    business_name: businessName,
    mrin,
    files: {
      mergedPack: { fileName: mergedFileName, mimeType: mergedBinary.mimeType || 'application/pdf' },
      invoiceFile: { fileName: invoiceFileName, mimeType: invoiceBinary.mimeType || 'application/pdf' },
    },
  },
  binary: { mergedPack: mergedBinary, invoiceFile: invoiceBinary },
}];

