// Comparison name, links and today's date (dd/mm/yy) for the logs
const comparisonName = $('Code139').first().json.files?.mergedPack?.fileName || '';
const pdfLink = $('Google Drive133').first().json.webViewLink || '';
const spreadsheetLink = 'https://docs.google.com/spreadsheets/d/' + ($('Copy file template27').first().json.id || '');
const today = new Date();
const formattedDate = `${String(today.getDate()).padStart(2, '0')}/${String(today.getMonth() + 1).padStart(2, '0')}/${String(today.getFullYear()).slice(2)}`;
return [{ json: { comparisonName, pdfLink, spreadsheetLink, formattedDate } }];
